<template><ul class="ui-tree"><li v-for="item in items" :key="item.key"><button type="button" :class="{'is-selected':item.key===modelValue}" @click="emit('update:modelValue',item.key)"><Icon :name="item.children?.length?'chevronRight':'document'" size="xs"/><span>{{ item.label }}</span></button><UiTree v-if="item.children?.length" :items="item.children" :model-value="modelValue" @update:model-value="emit('update:modelValue',$event)"/></li></ul></template>
<script setup lang="ts">import Icon from'@/components/icons/Icon.vue';export interface UiTreeItem{key:string;label:string;children?:UiTreeItem[]}defineOptions({name:'UiTree'});defineProps<{items:UiTreeItem[];modelValue?:string}>();const emit=defineEmits<{'update:modelValue':[string]}>();</script>
<style scoped>.ui-tree{display:grid;gap:2px;margin:0;padding:0 0 0 14px;list-style:none}.ui-tree:first-child{padding-left:0}.ui-tree button{display:flex;width:100%;height:30px;align-items:center;gap:6px;padding:0 8px;border:0;border-radius:4px;color:var(--ui-text-muted);background:transparent;text-align:left}.ui-tree button:hover,.ui-tree button.is-selected{color:var(--ui-text);background:var(--ui-surface-muted)}</style>
